// Accepts the hosted form, the webhook (JSON body) and the test sample, and returns one clean shape.
const j = $input.first().json;
const b = j.body || {};
const pick = (...vals) => {
  for (const v of vals) {
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};
const c = j.body ? b.consent : j['Permission'];
const consent = Array.isArray(c) ? c.length > 0 : (c === true || c === 'true' || c === 'yes');
const isForm = j['Full name'] !== undefined;

return [{
  json: {
    intakeId: 'INT-' + $now.toFormat('yyyyLLdd-HHmmss') + '-' + Math.floor(100 + Math.random() * 900),
    receivedAt: $now.toISO(),
    fullName: pick(b.fullName, j['Full name']),
    email: pick(b.email, j['Email']).toLowerCase(),
    phone: pick(b.phone, j['Phone']),
    areaSelf: pick(b.areaOfLaw, j['What type of legal help do you need?']),
    matterDescription: pick(b.matterDescription, j['Briefly describe your situation']).slice(0, 4000),
    incidentDateInput: pick(b.incidentDate, j['Date it happened (if any)']),
    opposingParty: pick(b.opposingParty, j['Other person or company involved']),
    preferredContact: pick(b.preferredContact, j['Best way to reach you']),
    urgencySelf: pick(b.urgencySelf, j['How time-sensitive is this?']),
    source: pick(b.source, isForm ? 'intake-form' : 'api'),
    consent
  }
}];

const intake = $('Control Panel').first().json;
const res = $input.first().json;
let t = {};
try {
  const text = (res.content && res.content[0] && res.content[0].text) || '';
  const m = text.match(/\{[\s\S]*\}/);
  t = JSON.parse(m ? m[0] : text);
} catch (e) {
  t = {};
}
const urgencies = ['low', 'medium', 'high', 'critical'];
const aiFailed = !t || typeof t.practiceArea !== 'string';
const arr = (v) => (Array.isArray(v) ? v.map((x) => String(x)).slice(0, 8) : []);
return [{
  json: {
    ...intake,
    practiceArea: aiFailed ? 'Unclassified' : t.practiceArea,
    subtype: aiFailed ? '' : String(t.subtype || ''),
    fitsFirm: aiFailed ? false : t.fitsFirm === true,
    urgency: urgencies.includes(t.urgency) ? t.urgency : 'medium',
    incidentDateAI: /^\d{4}-\d{2}-\d{2}$/.test(t.incidentDate || '') ? t.incidentDate : '',
    deadlineMentioned: String(t.deadlineMentioned || ''),
    summary: t.summary ? String(t.summary) : 'AI triage was unavailable. Review the original message.',
    partiesMentioned: arr(t.partiesMentioned),
    missingInfo: arr(t.missingInfo),
    language: String(t.language || '').slice(0, 8),
    safetyConcern: t.safetyConcern === true,
    aiFailed
  }
}];

// Preliminary aids only. An attorney must confirm conflicts and limitation periods.
const d = $('Parse Triage').first().json;
const parse = (s, fallback) => { try { return JSON.parse(s); } catch (e) { return fallback; } };
const routing = parse(d.attorneyRouting, {});
const solMap = parse(d.solYears, {});

// ---- 1. conflict screen (word-boundary name matching) ----
const norm = (s) => ' ' + String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim() + ' ';
const targets = [d.opposingParty, d.fullName, ...(d.partiesMentioned || [])]
  .map(norm)
  .filter((t) => t.trim().length >= 3);
const rows = $input.all().map((i) => i.json).filter((r) => r.Name);
const hits = [];
const seen = new Set();
for (const r of rows) {
  const n = norm(r.Name);
  if (n.trim().length < 3) continue;
  for (const t of targets) {
    if (t.includes(n) || n.includes(t)) {
      if (!seen.has(r.Name)) {
        seen.add(r.Name);
        hits.push({ name: String(r.Name), role: String(r.Role || ''), matter: String(r.Matter || '') });
      }
      break;
    }
  }
}
const conflictFound = hits.length > 0;

// ---- 2. limitation-date watch ----
const dateRe = /^\d{4}-\d{2}-\d{2}$/;
const incidentDateUsed = dateRe.test(d.incidentDateInput || '') ? d.incidentDateInput : (d.incidentDateAI || '');
const years = Number(solMap[d.practiceArea]);
let limitationDate = '';
let daysLeft = null;
let solNote = '';
if (incidentDateUsed && years > 0) {
  const inc = new Date(incidentDateUsed + 'T00:00:00Z');
  if (!isNaN(inc.getTime())) {
    const lim = new Date(inc);
    lim.setUTCFullYear(lim.getUTCFullYear() + years);
    limitationDate = lim.toISOString().slice(0, 10);
    daysLeft = Math.ceil((lim.getTime() - Date.now()) / 86400000);
    if (daysLeft < 0) solNote = 'The limitation period may already have passed (' + limitationDate + '). Attorney review needed urgently.';
    else if (daysLeft <= 90) solNote = 'Limitation date approaching: ' + limitationDate + ' (' + daysLeft + ' days). Verify for ' + d.jurisdiction + '.';
  }
}

// ---- 3. intake score (0-100) ----
const urgencyPts = { critical: 20, high: 15, medium: 8, low: 3 }[d.urgency] || 8;
const fitPts = d.fitsFirm ? 40 : 0;
const completePts =
  (d.opposingParty ? 8 : 0) +
  (incidentDateUsed ? 8 : 0) +
  ((d.missingInfo || []).length <= 1 ? 7 : 0) +
  ((d.matterDescription || '').length >= 200 ? 7 : 0);
const contactPts = (d.email ? 5 : 0) + (d.phone ? 5 : 0);
const score = Math.min(100, fitPts + completePts + contactPts + urgencyPts);
const scoreBreakdown = 'Fit ' + fitPts + '/40, Completeness ' + completePts + '/30, Contact ' + contactPts + '/10, Urgency ' + urgencyPts + '/20';

// ---- 4. priority tier ----
const selfUrgent = /court date|within 30 days/i.test(d.urgencySelf || '');
let tier = 3;
if (d.safetyConcern || d.urgency === 'critical' || selfUrgent || (daysLeft !== null && daysLeft <= 30)) tier = 1;
else if (d.urgency === 'high' || (daysLeft !== null && daysLeft <= 90) || score >= 75) tier = 2;
const slaText = { 1: 'Respond within 1 hour', 2: 'Respond within 24 hours', 3: 'Respond within 2 business days' }[tier];

// ---- 5. status & attorney ----
let status;
if (conflictFound) status = 'Conflict Hold';
else if (d.aiFailed || d.safetyConcern) status = 'Manual Review';
else if (!d.fitsFirm) status = 'Not a Fit';
else if (score < Number(d.minScore || 0)) status = 'Manual Review';
else status = 'Qualified';

const assignedAttorney = routing[d.practiceArea] || routing[d.areaSelf] || d.defaultAttorneyEmail;
const retentionUntil = new Date(Date.now() + Number(d.retentionDays || 730) * 86400000).toISOString().slice(0, 10);

return [{
  json: {
    ...d,
    conflictFound,
    conflictHits: hits,
    incidentDateUsed,
    limitationDate,
    daysLeft,
    solNote,
    score,
    scoreBreakdown,
    tier,
    slaText,
    status,
    assignedAttorney,
    retentionUntil
  }
}];

const d = $input.first().json;
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const C = { green: d.brandPrimary || '#02472f', gold: d.brandAccent || '#c9a040', cream: d.brandCream || '#f8f1df' };
const first = esc((d.fullName || '').split(' ')[0] || 'there');
const emergency = 'If you are in immediate danger or this is an emergency, call 911 (or your local emergency number) right away.';
const contactLine = [d.firmPhone, d.firmWebsite].filter(Boolean).map(esc).join(' &middot; ');

const shell = (preheader, inner, footer) => `<!doctype html><html><body style="margin:0;padding:0;background:${C.cream};">
<div style="display:none;max-height:0;overflow:hidden;">${esc(preheader)}</div>
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:${C.cream};padding:24px 12px;"><tr><td align="center">
<table role="presentation" width="600" cellspacing="0" cellpadding="0" style="max-width:600px;width:100%;background:#ffffff;border:1px solid #e6dcc3;border-radius:6px;overflow:hidden;">
<tr><td style="background:${C.green};padding:22px 28px;font-family:Georgia,'Times New Roman',serif;font-size:22px;color:#ffffff;letter-spacing:.3px;">${esc(d.firmName)}<div style="height:3px;width:44px;background:${C.gold};margin-top:10px;"></div></td></tr>
<tr><td style="padding:28px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#2b2b2b;">${inner}</td></tr>
<tr><td style="padding:16px 28px;background:#faf6ea;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:1.5;color:#6b6b6b;">${footer}</td></tr>
</table></td></tr></table></body></html>`;

const statusColor = { 'Conflict Hold': '#9b2c2c', 'Manual Review': '#b7791f', 'Qualified': '#1f7a4d', 'Not a Fit': '#5a6270' }[d.status] || '#5a6270';
const tierColor = { 1: '#9b2c2c', 2: '#b7791f', 3: '#2f6f8f' }[d.tier] || '#2f6f8f';
const pill = (t, bg) => `<span style="display:inline-block;background:${bg};color:#ffffff;padding:4px 12px;border-radius:12px;font-size:12px;font-weight:bold;margin:0 6px 6px 0;">${esc(t)}</span>`;
const row = (k, v) => `<tr><td style="padding:7px 0;width:150px;color:#7a7a7a;vertical-align:top;">${esc(k)}</td><td style="padding:7px 0;color:#222222;">${v}</td></tr>`;
const list = (arr) => (arr && arr.length)
  ? '<ul style="margin:6px 0 0 18px;padding:0;">' + arr.map((x) => `<li style="margin-bottom:4px;">${esc(x)}</li>`).join('') + '</ul>'
  : '<span style="color:#7a7a7a;">None</span>';
const h3 = (t) => `<h3 style="margin:22px 0 6px;font-size:14px;text-transform:uppercase;letter-spacing:.8px;color:${C.green};">${esc(t)}</h3>`;

// ---------- attorney brief ----------
const alerts = [];
if (d.safetyConcern) alerts.push('Possible safety concern in the message. Review immediately.');
if (d.conflictFound) alerts.push('Name match against the conflicts list. Hold all contact until an attorney clears it.');
if (d.solNote) alerts.push(d.solNote);
const alertBlock = alerts.length
  ? `<div style="background:#fdf1f0;border-left:4px solid #9b2c2c;padding:12px 14px;margin:0 0 18px;color:#7a1f1f;font-size:14px;">${alerts.map(esc).join('<br>')}</div>`
  : '';

const attorneyInner = `
<p style="margin:0 0 12px;">${pill(d.status, statusColor)}${pill('Tier ' + d.tier + ': ' + d.slaText, tierColor)}${pill('Score ' + d.score + '/100', '#4a5568')}</p>
${alertBlock}
<h2 style="margin:0 0 4px;font-size:22px;font-family:Georgia,serif;color:${C.green};">${esc(d.fullName)}</h2>
<p style="margin:0 0 16px;color:#7a7a7a;">${esc(d.practiceArea)}${d.subtype ? ' &middot; ' + esc(d.subtype) : ''} &middot; Ref ${esc(d.intakeId)}</p>
<table role="presentation" width="100%" cellspacing="0" cellpadding="0">
${row('Email', `<a href="mailto:${esc(d.email)}" style="color:${C.green};">${esc(d.email)}</a>`)}
${row('Phone', esc(d.phone) || 'Not provided')}
${row('Prefers', esc(d.preferredContact) || 'Not stated')}
${row('Assigned to', esc(d.assignedAttorney))}
${row('Other party', esc(d.opposingParty) || 'Not provided')}
${row('Incident date', esc(d.incidentDateUsed) || 'Not provided')}
${d.limitationDate ? row('Limitation date', esc(d.limitationDate) + ' (' + esc(d.daysLeft) + ' days). Verify for ' + esc(d.jurisdiction)) : ''}
${row('Writes in', esc(d.language) || 'unknown')}
${row('Score detail', esc(d.scoreBreakdown))}
</table>
${h3('Summary')}<p style="margin:0;">${esc(d.summary)}</p>
${h3('Missing information')}${list(d.missingInfo)}
${d.conflictFound ? h3('Possible conflicts') + list(d.conflictHits.map((h) => h.name + ' (' + h.role + ') - ' + h.matter)) : ''}
${h3('Original message')}<div style="background:#faf6ea;border-left:3px solid ${C.gold};padding:12px 14px;white-space:pre-wrap;">${esc(d.matterDescription)}</div>`;

const attorneyFooter = 'Confidential intake information. Triage is AI-assisted and preliminary: it is not legal advice, a conflicts clearance or a limitations determination. An attorney must review before any client contact or decision.';

// ---------- prospect: booking ----------
const button = `<a href="${esc(d.bookingLink)}" style="display:inline-block;background:${C.gold};color:#1d1d1d;text-decoration:none;font-weight:bold;padding:14px 28px;border-radius:4px;">Book your consultation</a>`;
const bookingInner = `
<p style="margin:0 0 14px;">Hello ${first},</p>
<p style="margin:0 0 14px;">Thank you for contacting <b>${esc(d.firmName)}</b>. Based on what you shared, we would like to speak with you about your matter. Please choose a time that suits you:</p>
<p style="margin:26px 0;">${button}</p>
${(d.missingInfo && d.missingInfo.length) ? '<p style="margin:0 0 6px;">To help us prepare, it would be useful to have these details ready:</p>' + list(d.missingInfo) : ''}
<p style="margin:18px 0 0;color:#7a7a7a;font-size:13px;">Your reference number is ${esc(d.intakeId)}.</p>
<p style="margin:14px 0 0;font-size:13px;">${esc(emergency)}</p>`;
const prospectFooter = 'This email is not legal advice, and no attorney-client relationship exists until our firm confirms it in writing. Please do not send confidential details by email before then.<br>' + contactLine;

// ---------- prospect: not a fit ----------
const declineInner = `
<p style="margin:0 0 14px;">Hello ${first},</p>
<p style="margin:0 0 14px;">Thank you for contacting <b>${esc(d.firmName)}</b>. Based on the information you shared, we are not able to assist with this matter.</p>
<p style="margin:0 0 14px;">Legal deadlines may apply to your situation. If it is time-sensitive, please contact another attorney or your local bar association referral service as soon as possible.</p>
<p style="margin:18px 0 0;color:#7a7a7a;font-size:13px;">Reference: ${esc(d.intakeId)}</p>
<p style="margin:14px 0 0;font-size:13px;">${esc(emergency)}</p>`;
const declineFooter = 'This email is not legal advice, and no attorney-client relationship has been formed.<br>' + contactLine;

// ---------- attorney follow-up reminder ----------
const followInner = `
<p style="margin:0 0 12px;">${pill('Follow-up reminder', '#b7791f')}${pill('Tier ' + d.tier, tierColor)}</p>
<h2 style="margin:0 0 8px;font-size:20px;font-family:Georgia,serif;color:${C.green};">Has ${esc(d.fullName)} booked?</h2>
<p style="margin:0 0 14px;">A booking link was sent ${esc(d.followUpHours)} hours ago for a ${esc(d.practiceArea)} inquiry. If there is no consultation on the calendar, a personal call or email may help.</p>
<table role="presentation" width="100%" cellspacing="0" cellpadding="0">
${row('Email', `<a href="mailto:${esc(d.email)}" style="color:${C.green};">${esc(d.email)}</a>`)}
${row('Phone', esc(d.phone) || 'Not provided')}
${row('Prefers', esc(d.preferredContact) || 'Not stated')}
${row('Reference', esc(d.intakeId))}
</table>`;

const safetyTag = d.safetyConcern ? ' - SAFETY CONCERN' : '';
return [{
  json: {
    ...d,
    attorneySubject: '[Tier ' + d.tier + '] ' + d.status + ' - ' + d.practiceArea + ' - ' + d.fullName + safetyTag,
    attorneyHtml: shell('New intake: ' + d.practiceArea + ' (' + d.status + ')', attorneyInner, attorneyFooter),
    bookingSubject: 'Schedule your consultation with ' + d.firmName,
    bookingHtml: shell('Choose a time to speak with our team', bookingInner, prospectFooter),
    declineSubject: 'Your inquiry to ' + d.firmName,
    declineHtml: shell('Regarding your recent inquiry', declineInner, declineFooter),
    followupSubject: 'Follow-up: has ' + d.fullName + ' booked? (Tier ' + d.tier + ')',
    followupHtml: shell('Follow-up reminder', followInner, attorneyFooter)
  }
}];
